use App\Models\ChannelGroup;
use App\Models\ChannelUrl;
use App\Models\Customer;
use App\Models\CustomerInvoce;
use App\Models\CustomerPlan;
use App\Models\IPTVConfig;
use App\Models\IPTVTaxVat;
use App\Models\User;
use Illuminate\Database\Seeder;
use Illuminate\Support\Carbon;
use Illuminate\Support\Facades\Hash;

class StoreDataSeeder extends Seeder
{

    /**
     * Seed test data for local development and manual validation.
     *
     * @return void
     */
    public function run()
    {
        $channelLogo = $this->readLogoAsBase64DataUri();


        User::updateOrCreate(
            ['email' => 'common.user@store.test'],
            [
                'name' => 'Common Demo User',
                'password' => Hash::make(User::STORE_DEMO_PASSWORD),
                'is_admin' => false,
                'active' => true,
                'email_verified_at' => now(),
            ]
        );


        User::updateOrCreate(
            ['email' => User::STORE_DEMO_EMAIL],
            [
                'name' => 'Demo Store',
                'password' => Hash::make(User::STORE_DEMO_PASSWORD),
                'is_admin' => true,
                'active' => true,
                'email_verified_at' => now(),
            ]
        );

        IPTVConfig::set('URL_CDN', true, 'bool');
        IPTVConfig::set('DOWNLOAD_FILE', true, 'bool');

        $tax10 = IPTVTaxVat::updateOrCreate(
            ['name' => 'VAT 10%'],
            ['porcent' => '10.00', 'active' => true]
        );

        $tax5 = IPTVTaxVat::updateOrCreate(
            ['name' => 'VAT 5%'],
            ['porcent' => '5.00', 'active' => true]
        );

        $mainPlan = CustomerPlan::updateOrCreate(
            ['name' => 'Plano Basico'],
            [
                'price' => 69.90,
                'active' => true,
                'additional' => false,
                'iptv_tax_vat_id' => $tax10->id,
            ]
        );

        $premiumPlan = CustomerPlan::updateOrCreate(
            ['name' => 'Plano Premium'],
            [
                'price' => 119.90,
                'active' => true,
                'additional' => false,
                'iptv_tax_vat_id' => $tax10->id,
            ]
        );

        $sportsAdditional = CustomerPlan::updateOrCreate(
            ['name' => 'Pacote Esportes'],
            [
                'price' => 29.90,
                'active' => true,
                'additional' => true,
                'iptv_tax_vat_id' => $tax5->id,
            ]
        );

        $cdnMain = ChannelCdn::updateOrCreate(
            ['slug' => 'main-cdn'],
            ['name' => 'Main CDN']
        );

        $cdnBackup = ChannelCdn::updateOrCreate(
            ['slug' => 'backup-cdn'],
            ['name' => 'Backup CDN']
        );

        $sportsGroup = ChannelGroup::updateOrCreate(
            ['name' => 'Esportes'],
            ['iptv_plan_id' => $mainPlan->id]
        );

        $moviesGroup = ChannelGroup::updateOrCreate(
            ['name' => 'Filmes'],
            ['iptv_plan_id' => $premiumPlan->id]
        );

        $openGroup = ChannelGroup::updateOrCreate(
            ['name' => 'Abertos'],
            ['iptv_plan_id' => null]
        );

        $sportTv = Channel::updateOrCreate(
            ['number' => 101],
            [
                'group_id' => $sportsGroup->id,
                'name' => 'Sport TV',
                'logo' => $channelLogo,
                'radio' => false,
            ]
        );

        $movieMax = Channel::updateOrCreate(
            ['number' => 201],
            [
                'group_id' => $moviesGroup->id,
                'name' => 'Movie Max',
                'logo' => $channelLogo,
                'radio' => false,
            ]
        );

        $newsOpen = Channel::updateOrCreate(
            ['number' => 301],
            [
                'group_id' => $openGroup->id,
                'name' => 'News Open',
                'logo' => $channelLogo,
                'radio' => false,
            ]
        );

        $radioPop = Channel::updateOrCreate(
            ['number' => 901],
            [
                'group_id' => $openGroup->id,
                'name' => 'Radio Pop',
                'logo' => $channelLogo,
                'radio' => true,
            ]
        );

        $this->upsertChannelStream($cdnMain->id, $sportTv->id, 'https://stream.main-cdn.test/sport-tv.m3u8');
        $this->upsertChannelStream($cdnMain->id, $movieMax->id, 'https://stream.main-cdn.test/movie-max.m3u8');
        $this->upsertChannelStream($cdnMain->id, $newsOpen->id, 'https://stream.main-cdn.test/news-open.m3u8');
        $this->upsertChannelStream($cdnMain->id, $radioPop->id, 'https://stream.main-cdn.test/radio-pop.m3u8');

        $this->upsertChannelStream($cdnBackup->id, $sportTv->id, 'https://stream.backup-cdn.test/sport-tv.m3u8');
        $this->upsertChannelStream($cdnBackup->id, $movieMax->id, 'https://stream.backup-cdn.test/movie-max.m3u8');
        $this->upsertChannelStream($cdnBackup->id, $newsOpen->id, 'https://stream.backup-cdn.test/news-open.m3u8');
        $this->upsertChannelStream($cdnBackup->id, $radioPop->id, 'https://stream.backup-cdn.test/radio-pop.m3u8');

        $activeCustomer = Customer::updateOrCreate(
            ['username' => 'cliente.ativo'],
            [
                'name' => 'Cliente Ativo',
                'auth_token_id' => '01TESTACTIVE000000000000000001',
                'auth_token_hash' => Hash::make('token-cliente-ativo'),
                'auth_token_last_used_at' => null,
                'auth_token_expires_at' => null,
                'auth_token_revoked_at' => null,
                'iptv_plan_id' => $mainPlan->id,
                'iptv_cdn_id' => $cdnMain->id,
                'active' => true,
                'due_day' => 10,
                'industry' => 'Streaming',
                'address' => 'Rua Alfa, 123',
                'phone' => '11999990001',
                'email' => 'cliente.ativo@iptv.test',
                'tax_no' => '000001',
            ]
        );

        $inactiveCustomer = Customer::updateOrCreate(
            ['username' => 'cliente.inativo'],
            [
                'name' => 'Cliente Inativo',
                'auth_token_id' => '01TESTINACTIVE0000000000000001',
                'auth_token_hash' => Hash::make('token-cliente-inativo'),
                'auth_token_last_used_at' => null,
                'auth_token_expires_at' => null,
                'auth_token_revoked_at' => null,
                'iptv_plan_id' => $premiumPlan->id,
                'iptv_cdn_id' => $cdnBackup->id,
                'active' => false,
                'due_day' => 20,
                'industry' => 'Hospitalidade',
                'address' => 'Rua Beta, 456',
                'phone' => '11999990002',
                'email' => 'cliente.inativo@iptv.test',
                'tax_no' => '000002',
            ]
        );

        $defeatedCustomer = Customer::updateOrCreate(
            ['username' => 'cliente.vencido'],
            [
                'name' => 'Cliente Vencido',
                'auth_token_id' => '01TESTDEFEATED000000000000001',
                'auth_token_hash' => Hash::make('token-cliente-vencido'),
                'auth_token_last_used_at' => null,
                'auth_token_expires_at' => null,
                'auth_token_revoked_at' => null,
                'iptv_plan_id' => $mainPlan->id,
                'iptv_cdn_id' => $cdnMain->id,
                'active' => true,
                'due_day' => 5,
                'industry' => 'Comercio',
                'address' => 'Rua Gama, 789',
                'phone' => '11999990003',
                'email' => 'cliente.vencido@iptv.test',
                'tax_no' => '000003',
            ]
        );

        $activeCustomer->plans_additional()->syncWithoutDetaching([$sportsAdditional->id]);

        $now = Carbon::now();

        CustomerInvoce::updateOrCreate(
            [
                'iptv_customer_id' => $activeCustomer->id,
                'duedate_at' => $now->copy()->day(10)->toDateString(),
            ],
            [
                'payment_at' => $now->copy()->day(9),
                'canceled_at' => null,
                'payment_data' => 'paid-via-seeder',
            ]
        );

        CustomerInvoce::updateOrCreate(
            [
                'iptv_customer_id' => $inactiveCustomer->id,
                'duedate_at' => $now->copy()->day(20)->toDateString(),
            ],
            [
                'payment_at' => null,
                'canceled_at' => $now->copy()->day(19),
                'payment_data' => null,
            ]
        );

        CustomerInvoce::updateOrCreate(
            [
                'iptv_customer_id' => $defeatedCustomer->id,
                'duedate_at' => $now->copy()->subMonthNoOverflow()->day(5)->toDateString(),
            ],
            [
                'payment_at' => null,
                'canceled_at' => null,
                'payment_data' => null,
            ]
        );

        if ($this->command) {
            $this->command->info('StoreDataSeeder executed.');
            $this->command->line('Demo: ' . User::STORE_DEMO_EMAIL . ' / ' . User::STORE_DEMO_PASSWORD);
        }
    }

    /**
     * Create or update stream URL for a channel + CDN pair.
     *
     * @return void
     */
    private function upsertChannelStream(int $cdnId, int $channelId, string $url)
    {
        ChannelUrl::updateOrCreate(
            [
                'iptv_cdn_id' => $cdnId,
                'iptv_channel_id' => $channelId,
            ],
            [
                'url_stream' => $url,
            ]
        );
    }

    /**
     * Build a data URI logo from an embedded base64 string.
     */
    private function readLogoAsBase64DataUri(): string
    {
        return   '';
    }
}
